"use client"
import { SearchX } from "lucide-react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"

// Composed locally: Atlas has no EmptyState component (CAND-030).
export function NoResults({ query, onClear }: { query: string; onClear: () => void }) {
  return (
    <div
      role="status"
      style={{
        display: "grid",
        justifyItems: "center",
        textAlign: "center",
        gap: "var(--atlas-spacing-3)",
        paddingBlock: "var(--atlas-spacing-12)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <SearchX aria-hidden="true" color="var(--atlas-foreground-subtle)" />
      <h2 style={{ margin: 0, fontSize: "var(--atlas-text-h3)", color: "var(--atlas-foreground)" }}>
        {query ? `No results for “${query}”` : "No matching invoices"}
      </h2>
      <p style={{ margin: 0, fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
        Try a different search or status, or clear the filters to see every invoice.
      </p>
      <div style={{ marginBlockStart: "var(--atlas-spacing-3)" }}>
        <Button variant="outline" size="md" onClick={onClear}>Clear filters</Button>
      </div>
    </div>
  )
}

